import{_ as o,o as a,c as t,a2 as n}from"./chunks/framework.CTx8wfac.js";const h=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"tooling/cli.md","filePath":"tooling/cli.md"}'),r={name:"tooling/cli.md"};function s(d,e,i,c,l,g){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>The <strong><code>bananajs</code></strong> CLI is a <strong>first-class product surface</strong>: scaffolding, codegen, static analysis, DB/OpenAPI tooling, and <strong>AI</strong> flows—including <strong><code>.bananarc.json</code></strong>, <strong><code>ai setup</code></strong>, and <strong><code>ai generate --module</code></strong> for DDD layouts (<a href="/banana-universe/guide/philosophy.html">Philosophy</a>, <a href="/banana-universe/tooling/ai-module-generation.html">AI module generation</a>).</p><p>Package: <strong><code>@banana-universe/bananajs-cli</code></strong> · Entry: <strong><code>bananajs</code></strong>. Source: <strong><code>packages/bananajs-cli/src/index.ts</code></strong> (Commander.js).</p><h2 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bananajs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bananajs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="bananajs-new-appname" tabindex="-1"><code>bananajs new [appName]</code> <a class="header-anchor" href="#bananajs-new-appname" aria-label="Permalink to &quot;`bananajs new [appName]`&quot;">​</a></h2><p>Scaffolds an app from <strong>built-in presets</strong> (MongoDB/Mongoose or SQL/TypeORM). Writes files under <strong><code>./&lt;appName&gt;</code></strong>—<strong>no git</strong> and no remote template.</p><ul><li>Prompts for app name if omitted (default suggestion: <strong><code>my-bananajs-app</code></strong>)</li><li>Interactive terminal: prompts for <strong>MongoDB</strong> vs <strong>SQL</strong> preset</li><li><strong><code>--preset &lt;id&gt;</code></strong> — <strong><code>mongodb</code></strong> | <strong><code>sql</code></strong> — skip the preset prompt (use in CI/scripts)</li><li>Non-interactive stdin (no TTY): defaults to <strong><code>sql</code></strong> if <strong><code>--preset</code></strong> is omitted; pass <strong><code>--preset</code></strong> explicitly to choose MongoDB or silence the default</li></ul><h2 id="bananajs-generate-type-name-alias-g" tabindex="-1"><code>bananajs generate &lt;type&gt; &lt;name&gt;</code> (alias: <code>g</code>) <a class="header-anchor" href="#bananajs-generate-type-name-alias-g" aria-label="Permalink to &quot;`bananajs generate &lt;type&gt; &lt;name&gt;` (alias: `g`)&quot;">​</a></h2><p><strong>Types:</strong> <code>controller</code> | <code>dto</code> | <code>middleware</code> | <strong><code>module</code></strong></p><ul><li><strong><code>controller</code> / <code>dto</code> / <code>middleware</code></strong> — writes <strong><code>cwd/&lt;name&gt;.controller.ts</code></strong> (or <code>.dto.ts</code> / <code>.middleware.ts</code>)</li><li><strong><code>module</code></strong> — layered <strong>DDD</strong> tree under <strong><code>--out</code></strong> (default <strong><code>./src</code></strong>): <code>domain/</code>, <code>application/</code>, <code>infrastructure/</code>, and <strong><code>&lt;kebab&gt;.controller.ts</code></strong><ul><li><strong><code>--orm typeorm|mongoose|none</code></strong> — infrastructure stub (default: <strong><code>typeorm</code></strong> in non-interactive mode; interactive prompt when TTY and <code>--orm</code> omitted)</li><li><strong><code>--out &lt;dir&gt;</code></strong> — base directory for generated folders</li></ul></li><li><strong><code>--dry-run</code></strong> — print content without writing</li></ul><p>See <a href="/banana-universe/guide/layered-architecture.html">Layered architecture &amp; DDD</a>.</p><h2 id="bananajs-routes" tabindex="-1"><code>bananajs routes</code> <a class="header-anchor" href="#bananajs-routes" aria-label="Permalink to &quot;`bananajs routes`&quot;">​</a></h2><p>Static <strong>AST scan</strong> of <strong><code>src/</code></strong> for <code>@Controller</code> and HTTP decorators — prints a colored route table.</p><h2 id="bananajs-migrate" tabindex="-1"><code>bananajs migrate</code> <a class="header-anchor" href="#bananajs-migrate" aria-label="Permalink to &quot;`bananajs migrate`&quot;">​</a></h2><p><strong>Express → BananaJS</strong> codemod: generates controller stubs from Express route patterns.</p><h2 id="bananajs-db" tabindex="-1"><code>bananajs db</code> <a class="header-anchor" href="#bananajs-db" aria-label="Permalink to &quot;`bananajs db`&quot;">​</a></h2><ul><li><strong><code>--status</code></strong> — runs <strong><code>typeorm migration:show</code></strong> when a TypeORM config is present; if <strong><code>mongoose</code></strong> is in <code>package.json</code>, prints a short note (no migrate CLI)</li></ul><h2 id="bananajs-openapi-export" tabindex="-1"><code>bananajs openapi export</code> <a class="header-anchor" href="#bananajs-openapi-export" aria-label="Permalink to &quot;`bananajs openapi export`&quot;">​</a></h2><ul><li><strong><code>--out &lt;path&gt;</code></strong> — OpenAPI spec output</li><li><strong><code>--client typescript</code></strong> — optional client generation (<code>openapi-typescript</code>)</li></ul><h2 id="bananajs-ai" tabindex="-1"><code>bananajs ai</code> <a class="header-anchor" href="#bananajs-ai" aria-label="Permalink to &quot;`bananajs ai`&quot;">​</a></h2><p>Subcommands:</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><strong><code>ai generate</code></strong></td><td><strong><code>--from-schema &lt;file&gt;</code></strong> (JSON Schema / OpenAPI) or <strong><code>--from-prompt &lt;text&gt;</code></strong> (LLM; needs provider env vars)</td></tr><tr><td><strong><code>ai doc</code></strong></td><td>JSDoc on controllers; <strong><code>--file</code></strong>, <strong><code>--dry-run</code></strong></td></tr><tr><td><strong><code>ai review</code></strong></td><td>LLM review; <strong><code>--file</code></strong></td></tr></tbody></table><p>Shared: <strong><code>--out &lt;dir&gt;</code></strong>, <strong><code>--dry-run</code></strong> where applicable.</p><div class="info custom-block"><p class="custom-block-title">DDD modules</p><p><strong><code>bananajs ai setup</code></strong>, <strong><code>.bananarc.json</code></strong>, and <strong><code>ai generate --module</code></strong> drive LLM-assisted DDD module generation. For deterministic scaffolding <strong>without</strong> an LLM, use <strong><code>bananajs generate module</code></strong>.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/banana-universe/tooling/ai-commands.html">AI commands</a></li><li><a href="/banana-universe/tooling/ai-module-generation.html">AI module generation</a></li><li><a href="/banana-universe/tooling/benchmarks.html">Benchmarks</a></li></ul>',27)])])}const u=o(r,[["render",s]]);export{h as __pageData,u as default};
